// ============================================================================
// CSI_2_apb: APB4 register wrapper around CSI_2_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/CSI_2.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/CSI_2.md
// ============================================================================
module CSI_2_apb #(
  parameter int LINE_BYTES = 512
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic rx_bit,
  input logic rx_valid
);
  localparam logic [31:0] ID_VALUE = 32'h43320200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [9:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd10) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_irq;
  logic          c_frame_active;
  logic [15:0]   c_frame_cnt;
  logic [15:0]   c_line_cnt;
  logic [7:0]    c_last_dt;
  logic [15:0]   c_last_wc;
  logic [3:0]    c_err_flags;
  logic [15:0]   c_lb_len;
  logic [8:0]    c_lb_addr;
  logic [7:0]    c_lb_rdata;
  CSI_2_top #(.LINE_BYTES(LINE_BYTES)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .rx_bit(rx_bit),
    .rx_valid(rx_valid),
    .irq(c_irq),
    .frame_active(c_frame_active),
    .frame_cnt(c_frame_cnt),
    .line_cnt(c_line_cnt),
    .last_dt(c_last_dt),
    .last_wc(c_last_wc),
    .err_flags(c_err_flags),
    .lb_len(c_lb_len),
    .lb_addr(c_lb_addr),
    .lb_rdata(c_lb_rdata)
  );

  // ---------------- registers ----------------
  logic [0:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [8:0] r_LB_ADDR;   // 12'h020 LB_ADDR

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_LB_ADDR <= 9'h0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[0:0] & wmask[0:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[8]) r_LB_ADDR <= (r_LB_ADDR & ~wmask[8:0]) | (PWDATA[8:0] & wmask[8:0]);
    end
  end

  // ---------------- core inputs ----------------
  assign c_lb_addr = r_LB_ADDR[8:0];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'({c_lb_len, c_err_flags, c_frame_active});
      10'd6: apb_rdata = 32'({c_line_cnt, c_frame_cnt});
      10'd7: apb_rdata = 32'({c_last_wc, c_last_dt});
      10'd8: apb_rdata = 32'(r_LB_ADDR);
      10'd9: apb_rdata = 32'({c_lb_rdata});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
